CREATE TABLE anamneses(student_id TEXT PRIMARY KEY REFERENCES students(id),org_id TEXT NOT NULL REFERENCES organizations(id),version TEXT NOT NULL,answers TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL CHECK(status IN ('draft','complete')),training_consent INTEGER NOT NULL CHECK(training_consent IN (0,1)),nutrition_consent INTEGER NOT NULL CHECK(nutrition_consent IN (0,1)),consent_version TEXT NOT NULL,consented_at INTEGER NOT NULL,completed_at INTEGER,revision INTEGER NOT NULL DEFAULT 1,attention_review INTEGER NOT NULL CHECK(attention_review IN (0,1)),reviewed_by TEXT REFERENCES users(id),reviewed_revision INTEGER,updated_at INTEGER NOT NULL);
CREATE INDEX anamneses_org ON anamneses(org_id,status);
